arguments.file_text:
@page "/settings"
@rendermode InteractiveServer

@namespace sv_7225a5d1dbcc4079bef56cae920758e5.Components.Pages.Settings

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection"
                     OnSectionChanged="section => _activeSection = section" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
}

/* Settings Dashboard Layout */
.settings-dashboard {
    display: flex;
    gap: 0;
    min-height: calc(100vh - 120px);
    margin: -1.1rem -1.5rem;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding-top: 1rem;
}

.settings-nav-link {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    padding: 0.65rem 1.25rem;
    border: none;
    background: none;
    color: #495057;
    text-align: left;
    font-size: 0.95rem;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
    border-left-color: #0d6efd;
}

.settings-nav-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section h3 {
    font-weight: 600;
    border-bottom: 2px solid #e9ecef;
    padding-bottom: 0.75rem;
}

/* Appearance Preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.2s ease;
}

.appearance-preview .preview-header {
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-bottom: 1px solid #dee2e6;
}

.appearance-preview .preview-body {
    padding: 1rem;
}

.appearance-preview.preview-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.appearance-preview.preview-dark .preview-header {
    background: #2d2d2d;
    border-color: #444;
}

.appearance-preview.preview-compact .preview-body {
    padding: 0.5rem 0.75rem;
}

.appearance-preview.preview-compact .preview-header {
    padding: 0.4rem 0.75rem;
}

/* Responsive */
@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        min-width: 100%;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
        padding-top: 0.5rem;
        padding-bottom: 0.5rem;
    }

    .settings-sidebar .nav {
        flex-direction: row;
        overflow-x: auto;
    }

    .settings-nav-link {
        border-left: none;
        border-bottom: 3px solid transparent;
        white-space: nowrap;
    }

    .settings-nav-link.active {
        border-left-color: transparent;
        border-bottom-color: #0d6efd;
    }
}

